---package.json---
{
  "name": "hintlab",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "description": "HintLab — a debugging tutor for programming labs",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "dev": "tsx watch src/server.ts",
    "start": "tsx src/server.ts",
    "build": "tsc",
    "typecheck": "tsc --noEmit",
    "test:runner": "tsx scripts/check-runner.ts",
    "check:agent": "tsx scripts/check-agent.ts"
  },
  "dependencies": {
    "@cline/sdk": "^0.0.90",
    "express": "^5.2.1",
    "zod": "^4.6.5"
  },
  "devDependencies": {
    "@types/express": "^5.0.6",
    "@types/node": "^26.6.4",
    "tsx": "^4.23.15",
    "typescript": "^7.0.2"
  }
}

  1 | import fs from "node:fs";
  2 | import path from "node:path";
  3 | import express from "express";
  4 | import type { NextFunction, Request, Response } from "express";
  5 | import { isSlug, listAssignments, loadAssignment } from "./assignments";
  6 | import { nextHint, startSession } from "./agent";
  7 | import { HEARTBEAT_MS } from "./config";
  8 | import { runAssignment } from "./runner";
  9 | import {
 10 |   addClient,
 11 |   createSession,
 12 |   emitEvent,
 13 |   getSession,
 14 |   removeClient,
 15 |   setStatus,
 16 | } from "./sessions";
 17 | import { openSse, writeSseComment } from "./sse";
 18 | import type { Assignment } from "./types";
 19 | 
 20 | export function createApp(): express.Express {
 21 |   const app = express();
 22 |   app.use(express.json({ limit: "1mb" }));
 23 | 
 24 |   app.get("/api/health", (_req, res) => {
 25 |     res.json({ status: "ok" });
 26 |   });
 27 | 
 28 |   app.get("/api/assignments", (_req, res) => {
 29 |     const assignments = listAssignments();
 30 |     res.json(
 31 |       assignments.map((a) => ({
 32 |         id: a.id,
 33 |         language: a.language,
 34 |         statement: a.statement,
 35 |         starterCode: a.starterCode,
 36 |       })),
 37 |     );
 38 |   });
 39 | 
 40 |   app.post("/api/session", async (req: Request, res: Response, next: NextFunction) => {
 41 |     try {
 42 |       const body: unknown = req.body;
 43 |       if (typeof body !== "object" || body === null || Array.isArray(body)) {
 44 |         res.status(400).json({ error: "request body must be a JSON object" });
 45 |         return;
 46 |       }
 47 | 
 48 |       const assignmentId = (body as Record<string, unknown>).assignmentId;
 49 |       if (!isSlug(assignmentId)) {
 50 |         res.status(400).json({ error: "assignmentId is required and must be a plain slug" });
 51 |         return;
 52 |       }
 53 | 
 54 |       let assignment: Assignment;
 55 |       try {
 56 |         assignment = loadAssignment(assignmentId);
 57 |       } catch {
 58 |         res.status(404).json({ error: `unknown assignment: ${assignmentId}` });
 59 |         return;
 60 |       }
 61 | 
 62 |       const codeRaw = (body as Record<string, unknown>).code;
 63 |       let code: string;
 64 |       if (codeRaw === undefined || codeRaw === null || codeRaw === "") {
 65 |         code = assignment.starterCode;
 66 |       } else if (typeof codeRaw !== "string") {
 67 |         res.status(400).json({ error: "code must be a string" });
 68 |         return;
 69 |       } else {
 70 |         code = codeRaw;
 71 |       }
 72 | 
 73 |       // Run the runner WITHOUT cleanup so the temp workdir persists for the
 74 |       // agent. The workdir is the agent's sandbox and lives until the session
 75 |       // ends/TTL, at which point the session cleanup loop removes it.
 76 |       const testResults = await runAssignment(assignment, code, { cleanup: false });
 77 | 
 78 |       const session = createSession({
 79 |         assignmentId: assignment.id,
 80 |         language: assignment.language,
 81 |         statement: assignment.statement,
 82 |         workdir: testResults.sandboxDir,
 83 |         testResults,
 84 |       });
 85 | 
 86 |       // Record the test results first so they replay before any agent event.
 87 |       emitEvent(session, "test_results", testResults);
 88 |       setStatus(session, "running");
 89 | 
 90 |       // Fire-and-forget: ask the agent for a level-1 hint in the background.
 91 |       startSession(session.id).catch((err) => {
 92 |         emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
 93 |         setStatus(session, "error");
 94 |       });
 95 | 
 96 |       res.json({ sessionId: session.id, testResults });
 97 |     } catch (err) {
 98 |       next(err);
 99 |     }
100 |   });
101 | 
102 |   app.get("/api/session/:id/stream", (req: Request, res: Response) => {
103 |     const session = getSession(String(req.params.id));
104 |     if (!session) {
105 |       res.status(404).json({ error: "unknown session" });
106 |       return;
107 |     }
108 | 
109 |     openSse(res);
110 |     res.write(": connected\n\n");
111 |     addClient(session, res); // replays buffered events + registers for live events
112 | 
113 |     const heartbeat = setInterval(() => {
114 |       try {
115 |         writeSseComment(res, "ping");
116 |       } catch {
117 |         /* ignore */
118 |       }
119 |     }, HEARTBEAT_MS);
120 |     heartbeat.unref();
121 | 
122 |     res.on("close", () => {
123 |       clearInterval(heartbeat);
124 |       removeClient(session, res);
125 |     });
126 |   });
127 | 
128 |   app.post("/api/session/:id/next-hint", async (req: Request, res: Response, next: NextFunction) => {
129 |     try {
130 |       const session = getSession(String(req.params.id));
131 |       if (!session) {
132 |         res.status(404).json({ error: "unknown session" });
133 |         return;
134 |       }
135 |       if (session.busy) {
136 |         res.status(409).json({ error: "agent is still busy", status: session.status });
137 |         return;
138 |       }
139 |       const result = await nextHint(session.id);
140 |       res.json(result);
141 |     } catch (err) {
142 |       const status = (err as { status?: number }).status;
143 |       if (status === 404) {
144 |         res.status(404).json({ error: "unknown session" });
145 |         return;
146 |       }
147 |       if (status === 409) {
148 |         res.status(409).json({ error: "agent is still busy" });
149 |         return;
150 |       }
151 |       next(err);
152 |     }
153 |   });
154 | 
155 |   const webDir = path.resolve(process.cwd(), "web");
156 |   if (fs.existsSync(webDir)) {
157 |     app.use(express.static(webDir));
158 |   }
159 | 
160 |   // eslint-disable-next-line @typescript-eslint/no-explicit-any
161 |   app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
162 |     const status = typeof err?.status === "number" ? err.status : 500;
163 |     if (status >= 400 && status < 500) {
164 |       res.status(status).json({ error: "invalid request body" });
165 |       return;
166 |     }
167 |     console.error(err);
168 |     res.status(500).json({ error: "internal server error" });
169 |   });
170 | 
171 |   return app;
172 | }

  1 | import path from "node:path";
  2 | import { ClineCore, createTool } from "@cline/sdk";
  3 | import type { AgentTool } from "@cline/sdk";
  4 | import { z } from "zod";
  5 | import { allowCommands, extractCommands } from "./allowlist";
  6 | import { HINTLAB_MODEL_ID, HINTLAB_PROVIDER_ID } from "./config";
  7 | import { checkHint } from "./hintGuard";
  8 | import {
  9 |   emitEvent,
 10 |   getSession,
 11 |   recordHint,
 12 |   registerAgentSession,
 13 |   setStatus,
 14 |   setStopAgentHook,
 15 | } from "./sessions";
 16 | import type { Session } from "./types";
 17 | 
 18 | let clineCorePromise: Promise<ClineCore> | null = null;
 19 | 
 20 | const SYSTEM_PROMPT = [
 21 |   "You are HintLab, a programming tutor that helps a student debug their lab assignment.",
 22 |   "",
 23 |   "Diagnose why the student's program fails its tests, then help the student figure it out",
 24 |   "on their own. You may read files (read_files, search_codebase) and run allow-listed shell",
 25 |   "commands (run_commands) to inspect and test the program.",
 26 |   "",
 27 |   "Hard rules:",
 28 |   "- NEVER write, edit, or show corrected code — not in tool calls, not in your text.",
 29 |   "  The file-editing tools are disabled for you; do not attempt them.",
 30 |   "- Do NOT put code, code snippets, or a rewritten solution in any message or hint.",
 31 |   "- The ONLY way to help is through the give_hint tool. Call it exactly once per turn, at",
 32 |   "  the level you were asked for.",
 33 |   "- give_hint levels: 1 = a conceptual nudge; 2 = point to the area or line of the bug;",
 34 |   "  3 = a near-explicit explanation of the bug and the concept. No level may include code.",
 35 |   "- After calling give_hint, finish your turn with a brief, code-free message.",
 36 |   "- run_commands already executes with the assignment workdir as its current directory, so",
 37 |   "  use RELATIVE commands only (python3 main.py, ./main, cat main.py, echo \"...\" | python3",
 38 |   "  main.py). Do NOT use `cd`, absolute paths, or shell separators like `;`/`&&`.",
 39 | ].join("\n");
 40 | 
 41 | const GIVE_HINT_DESCRIPTION = [
 42 |   "Show the student exactly one hint at the requested level.",
 43 |   "level 1 = a conceptual nudge; level 2 = point to the area or line of the bug;",
 44 |   "level 3 = a near-explicit explanation of the bug and the underlying concept.",
 45 |   "Never include code or a corrected solution in the text. Use plain prose only.",
 46 |   "An optional short `tag` (e.g. \"off-by-one\") is fine.",
 47 | ].join(" ");
 48 | 
 49 | /**
 50 |  * The shared give_hint tool. It is the only hint sink: the server-side guard runs
 51 |  * here before a hint is recorded, and a rejected hint becomes a tool error so the
 52 |  * model rephrases instead of the hint reaching the student.
 53 |  */
 54 | const giveHintTool = createTool({
 55 |   name: "give_hint",
 56 |   description: GIVE_HINT_DESCRIPTION,
 57 |   inputSchema: z.object({
 58 |     level: z.number().int().min(1).max(3),
 59 |     tag: z.string().optional(),
 60 |     text: z.string(),
 61 |   }),
 62 |   async execute(input, context) {
 63 |     const session = context.sessionId ? getSession(context.sessionId) : undefined;
 64 |     const wanted = session?.currentHintLevel ?? input.level;
 65 | 
 66 |     if (session && input.level !== wanted) {
 67 |       emitEvent(session, "hint_rejected", {
 68 |         level: input.level,
 69 |         wantedLevel: wanted,
 70 |         reason: "wrong level",
 71 |       });
 72 |       throw new Error(
 73 |         `You were asked for a level ${wanted} hint, but called give_hint with level ${input.level}. ` +
 74 |           `Call give_hint again with level ${wanted}.`,
 75 |       );
 76 |     }
 77 | 
 78 |     if (session && session.hints.some((h) => h.level === input.level)) {
 79 |       // This level was already delivered; tell the model to stop without erroring,
 80 |       // so it finishes its turn instead of retrying forever.
 81 |       return {
 82 |         shown: false,
 83 |         alreadyDelivered: true,
 84 |         message: `The level ${input.level} hint was already delivered. Do not call give_hint again; finish your turn.`,
 85 |       };
 86 |     }
 87 | 
 88 |     const guard = checkHint(input.text);
 89 |     if (!guard.ok) {
 90 |       if (session) {
 91 |         emitEvent(session, "hint_rejected", { level: input.level, reason: guard.reason, text: input.text });
 92 |       }
 93 |       throw new Error(
 94 |         `HintLab rejected this hint: ${guard.reason}. Rephrase the hint in plain prose with no code, ` +
 95 |           `then call give_hint again.`,
 96 |       );
 97 |     }
 98 | 
 99 |     const hint = {
100 |       level: input.level as 1 | 2 | 3,
101 |       tag: input.tag,
102 |       text: input.text,
103 |       at: new Date().toISOString(),
104 |     };
105 |     if (session) {
106 |       recordHint(session, hint);
107 |     }
108 |     return { shown: true, level: input.level };
109 |   },
110 | });
111 | 
112 | 
113 | function toolPolicies() {
114 |   return {
115 |     read_files: { autoApprove: true },
116 |     search_codebase: { autoApprove: true },
117 |     run_commands: { autoApprove: false },
118 |     editor: { enabled: false },
119 |     apply_patch: { enabled: false },
120 |     fetch_web_content: { enabled: false },
121 |     skills: { enabled: false },
122 |     ask_question: { enabled: false },
123 |     submit_and_exit: { enabled: false },
124 |     give_hint: { autoApprove: true },
125 |   };
126 | }
127 | 
128 | function capabilities() {
129 |   return {
130 |     requestToolApproval: async (req: {
131 |       sessionId: string;
132 |       toolName: string;
133 |       toolCallId: string;
134 |       input: unknown;
135 |     }) => {
136 |       const session = getSession(req.sessionId);
137 |       const commands = extractCommands(req.input);
138 | 
139 |       if (req.toolName !== "run_commands") {
140 |         const reason = `tool "${req.toolName}" requires approval and is not allowed in HintLab`;
141 |         if (session) {
142 |           emitEvent(session, "approval", {
143 |             toolName: req.toolName,
144 |             toolCallId: req.toolCallId,
145 |             commands,
146 |             allowed: false,
147 |             reason,
148 |           });
149 |         }
150 |         return { approved: false, reason };
151 |       }
152 | 
153 |       const decision = allowCommands(commands);
154 |       if (session) {
155 |         emitEvent(session, "approval", {
156 |           toolName: req.toolName,
157 |           toolCallId: req.toolCallId,
158 |           commands,
159 |           allowed: decision.allowed,
160 |           reason: decision.reason,
161 |         });
162 |       }
163 |       return decision.allowed
164 |         ? { approved: true }
165 |         : { approved: false, reason: decision.reason ?? "command not on the HintLab allow-list" };
166 |     },
167 |   };
168 | }
169 | 
170 | /** Map the raw SDK events to HintLab SSE events, routed by session id. */
171 | function handleCoreEvent(e: {
172 |   type: string;
173 |   payload?: { sessionId?: string; event?: Record<string, unknown>; [k: string]: unknown };
174 | }): void {
175 |   const sessionId = e.payload?.sessionId;
176 |   if (!sessionId) return;
177 |   const session = getSession(sessionId);
178 |   if (!session) return;
179 | 
180 |   if (e.type === "agent_event") {
181 |     const ev = e.payload?.event as Record<string, unknown> | undefined;
182 |     if (!ev) return;
183 |     switch (ev.type) {
184 |       case "content_start":
185 |         if (ev.contentType === "tool") {
186 |           emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, input: ev.input });
187 |         } else if (ev.contentType === "text") {
188 |           emitEvent(session, "agent_text", { text: ev.text ?? "", phase: "start" });
189 |         } else if (ev.contentType === "reasoning") {
190 |           emitEvent(session, "reasoning", { text: ev.reasoning ?? "", redacted: ev.redacted });
191 |         }
192 |         break;
193 |       case "content_update":
194 |         if (ev.contentType === "tool") {
195 |           emitEvent(session, "tool_call", { toolName: ev.toolName, toolCallId: ev.toolCallId, update: ev.update });
196 |         }
197 |         break;
198 |       case "content_end":
199 |         if (ev.contentType === "tool") {
200 |           emitEvent(session, "tool_result", {
201 |             toolName: ev.toolName,
202 |             toolCallId: ev.toolCallId,
203 |             output: ev.output,
204 |             error: ev.error,
205 |             durationMs: ev.durationMs,
206 |           });
207 |         } else if (ev.contentType === "text") {
208 |           emitEvent(session, "agent_text", { text: ev.text ?? "", phase: "end" });
209 |         } else if (ev.contentType === "reasoning") {
210 |           emitEvent(session, "reasoning", { text: ev.reasoning ?? "", redacted: ev.redacted, phase: "end" });
211 |         }
212 |         break;
213 |       case "iteration_start":
214 |         emitEvent(session, "status", { iteration: ev.iteration, phase: "iteration_start" });
215 |         break;
216 |       case "iteration_end":
217 |         emitEvent(session, "status", { iteration: ev.iteration, toolCallCount: ev.toolCallCount, phase: "iteration_end" });
218 |         break;
219 |       case "usage":
220 |         emitEvent(session, "status", {
221 |           usage: {
222 |             inputTokens: ev.inputTokens,
223 |             outputTokens: ev.outputTokens,
224 |             totalInputTokens: ev.totalInputTokens,
225 |             totalOutputTokens: ev.totalOutputTokens,
226 |           },
227 |         });
228 |         break;
229 |       case "notice":
230 |         emitEvent(session, "status", { noticeType: ev.noticeType, message: ev.message });
231 |         break;
232 |       case "done":
233 |         emitEvent(session, "done", { reason: ev.reason, text: ev.text, iterations: ev.iterations });
234 |         break;
235 |       case "error":
236 |         emitEvent(session, "error", {
237 |           message: ev.error instanceof Error ? ev.error.message : String(ev.error),
238 |           recoverable: ev.recoverable,
239 |           iteration: ev.iteration,
240 |         });
241 |         break;
242 |       default:
243 |         break;
244 |     }
245 |     return;
246 |   }
247 | 
248 |   if (e.type === "status") {
249 |     emitEvent(session, "status", { status: e.payload?.status });
250 |   } else if (e.type === "ended") {
251 |     emitEvent(session, "done", { reason: e.payload?.reason });
252 |   } else if (e.type === "hook") {
253 |     const payload = e.payload as Record<string, unknown>;
254 |     emitEvent(session, "status", { hook: payload.hookEventName, toolName: payload.toolName });
255 |   }
256 | }
257 | 
258 | 
259 | /** Lazily create the one shared ClineCore instance and subscribe once. */
260 | async function getCline(): Promise<ClineCore> {
261 |   if (!clineCorePromise) {
262 |     clineCorePromise = (async () => {
263 |       const cline = await ClineCore.create({ clientName: "hintlab", backendMode: "local" });
264 |       cline.subscribe((e: unknown) => handleCoreEvent(e as Parameters<typeof handleCoreEvent>[0]));
265 |       return cline;
266 |     })();
267 |   }
268 |   return clineCorePromise;
269 | }
270 | 
271 | // Register the hook so session cleanup can stop the SDK session too.
272 | setStopAgentHook((agentSessionId) => {
273 |   if (!clineCorePromise) return;
274 |   clineCorePromise
275 |     .then((cline) => cline.stop(agentSessionId).catch(() => undefined))
276 |     .catch(() => undefined);
277 | });
278 | 
279 | function buildTestResultsText(session: Session): string {
280 |   const lines: string[] = [];
281 |   for (const t of session.testResults.tests) {
282 |     lines.push(
283 |       `- ${t.name}: input=${JSON.stringify(t.input)} expected=${JSON.stringify(t.expected)} got=${JSON.stringify(t.got)} ` +
284 |         `(passed=${t.passed})`,
285 |     );
286 |   }
287 |   if (session.testResults.build && !session.testResults.build.ok) {
288 |     lines.push(`(build failed: ${session.testResults.build.stderr.trim().slice(0, 400)})`);
289 |   }
290 |   return lines.join("\n");
291 | }
292 | 
293 | function buildFirstPrompt(session: Session, mainPath: string, testsPath: string): string {
294 |   return [
295 |     `The student is working on assignment "${session.assignmentId}" (${session.language}): ${session.statement}`,
296 |     "",
297 |     `Files (use these ABSOLUTE paths with read_files):`,
298 |     `- Student code: ${mainPath}`,
299 |     `- Tests: ${testsPath}`,
300 |     "",
301 |     "The program was already run against the test cases. Results:",
302 |     buildTestResultsText(session),
303 |     "",
304 |     "Diagnose the root cause of the failure(s). Read the files and run allow-listed commands",
305 |     "to confirm your diagnosis (run_commands already runs inside the workdir, so use relative",
306 |     "commands: python3 main.py / echo \"...\" | python3 main.py / cat main.py / cat tests.json,",
307 |     "or for C the gcc build and ./main — never `cd` or absolute paths). Then call the give_hint",
308 |     "tool EXACTLY ONCE with level 1 (a conceptual nudge). Do not write or show corrected code,",
309 |     "and do not call give_hint more than once.",
310 |   ].join("\n");
311 | }
312 | 
313 | function buildNextPrompt(_session: Session, level: number): string {
314 |   return [
315 |     "The student is still stuck and asked for the next hint.",
316 |     `Give the next hint at level ${level}`,
317 |     "(1 = conceptual nudge, 2 = where to look, 3 = near-explicit concept).",
318 |     `Call the give_hint tool EXACTLY ONCE with level ${level}. Do not write or show corrected code.`,
319 |   ].join("\n");
320 | }
321 | 
322 | /** Run the first (level-1) agent turn in the background for a session. */
323 | export async function startSession(sessionId: string): Promise<void> {
324 |   const session = getSession(sessionId);
325 |   if (!session) return;
326 | 
327 |   const mainFile = session.language === "python" ? "main.py" : "main.c";
328 |   const mainPath = path.resolve(session.workdir, mainFile);
329 |   const testsPath = path.resolve(session.workdir, "tests.json");
330 | 
331 |   const cline = await getCline();
332 |   session.busy = true;
333 |   setStatus(session, "running");
334 | 
335 |   try {
336 |     const result = await cline.start({
337 |       interactive: true,
338 |       prompt: buildFirstPrompt(session, mainPath, testsPath),
339 |       config: {
340 |         sessionId: session.id,
341 |         providerId: HINTLAB_PROVIDER_ID,
342 |         modelId: HINTLAB_MODEL_ID,
343 |         temperature: 0,
344 |         systemPrompt: SYSTEM_PROMPT,
345 |         // session.workdir is the runner's temp sandbox dir, kept alive for the
346 |         // agent via runAssignment(..., { cleanup: false }) in app.ts. It is the
347 |         // agent's whole sandbox and is removed by the session cleanup loop when
348 |         // the session ends/TTL expires (see sessions.ts deleteSession).
349 |         cwd: session.workdir,
350 |         workspaceRoot: session.workdir,
351 |         enableTools: true,
352 |         enableSpawnAgent: false,
353 |         enableAgentTeams: false,
354 |         extraTools: [giveHintTool as unknown as AgentTool],
355 |       },
356 |       toolPolicies: toolPolicies(),
357 |       capabilities: capabilities(),
358 |     });
359 | 
360 |     session.agentSessionId = result.sessionId;
361 |     registerAgentSession(result.sessionId, session.id);
362 |     const finishReason = (result.result as { finishReason?: string } | undefined)?.finishReason;
363 |     emitEvent(session, "status", { message: "initial agent turn finished", finishReason });
364 |   } catch (err) {
365 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
366 |     setStatus(session, "error");
367 |   } finally {
368 |     session.busy = false;
369 |     if (session.status !== "error") {
370 |       setStatus(session, session.hints.length >= 3 ? "complete" : "idle");
371 |     }
372 |   }
373 | }
374 | 
375 | /** Ask the agent for the next hint level (2, then 3). Returns after the turn completes. */
376 | export async function nextHint(sessionId: string): Promise<{ level: number; status: string; message?: string }> {
377 |   const session = getSession(sessionId);
378 |   if (!session) throw Object.assign(new Error("unknown session"), { status: 404 });
379 |   if (session.busy) throw Object.assign(new Error("agent is still busy"), { status: 409 });
380 |   if (session.hints.length >= 3) {
381 |     return { level: 3, status: "complete", message: "All three hint levels have already been delivered." };
382 |   }
383 | 
384 |   const nextLevel = Math.min(session.hints.length + 1, 3);
385 |   session.currentHintLevel = nextLevel;
386 |   session.busy = true;
387 |   setStatus(session, "running");
388 | 
389 |   const cline = await getCline();
390 |   try {
391 |     const result = await cline.send({
392 |       sessionId: session.agentSessionId ?? session.id,
393 |       prompt: buildNextPrompt(session, nextLevel),
394 |     });
395 |     const finishReason = (result as { finishReason?: string } | undefined)?.finishReason;
396 |     emitEvent(session, "status", { message: `level ${nextLevel} agent turn finished`, finishReason });
397 |   } catch (err) {
398 |     emitEvent(session, "error", { message: err instanceof Error ? err.message : String(err) });
399 |     setStatus(session, "error");
400 |   } finally {
401 |     session.busy = false;
402 |     if (session.status !== "error") {
