120 | async function e2e(): Promise<void> {
121 |   const assignment = loadAssignment("sum-of-list");
122 |   const code = assignment.starterCode;
123 | 
124 |   const postRes = await fetch(`${BASE}/api/session`, {
125 |     method: "POST",
126 |     headers: { "content-type": "application/json" },
127 |     body: JSON.stringify({ assignmentId: "sum-of-list", code }),
128 |   });
129 |   check(postRes.status === 200, `POST /api/session -> 200 (got ${postRes.status})`);
130 |   const postBody = (await postRes.json()) as { sessionId?: string; testResults?: { total?: number; passed?: number } };
131 |   const sessionId = postBody.sessionId;
132 |   check(!!sessionId, "POST /api/session returns a sessionId");
133 |   check(
134 |     postBody.testResults?.total === 4 && postBody.testResults?.passed === 0,
135 |     `sum-of-list buggy starter fails 0/4 (got ${postBody.testResults?.passed}/${postBody.testResults?.total})`,
136 |   );
137 |   console.log("\n=== session ===");
138 |   console.log("assignmentId: sum-of-list");
139 |   console.log("sessionId:", sessionId);
140 | 
141 |   const events: SseRecord[] = [];
142 |   const hints: Array<{ level: number; tag?: string; text: string }> = [];
143 |   const approvals: Array<{ toolName?: string; commands?: string[]; allowed?: boolean; reason?: string }> = [];
144 |   const toolCalls: Array<{ toolName?: string }> = [];
145 |   const eventTypes = new Set<string>();
146 |   let lastStatus = "";
147 | 
148 |   const controller = new AbortController();
149 |   const streamTask = (async () => {
150 |     const res = await fetch(`${BASE}/api/session/${sessionId}/stream`, { signal: controller.signal });
151 |     check(res.status === 200, `SSE stream -> 200 (got ${res.status})`);
152 |     if (!res.body) return;
153 |     const reader = res.body.getReader();
154 |     const decoder = new TextDecoder();
155 |     let buffer = "";
156 |     try {
157 |       for (;;) {
158 |         const { done, value } = await reader.read();
159 |         if (done) break;
160 |         buffer += decoder.decode(value, { stream: true });
161 |         let idx: number;
162 |         while ((idx = buffer.indexOf("\n\n")) >= 0) {
163 |           const block = buffer.slice(0, idx);
164 |           buffer = buffer.slice(idx + 2);
165 |           let name = "message";
166 |           const dataLines: string[] = [];
167 |           for (const line of block.split("\n")) {
168 |             if (line.startsWith(":")) continue;
169 |             if (line.startsWith("event:")) name = line.slice(6).trim();
170 |             else if (line.startsWith("data:")) dataLines.push(line.slice(5).trimStart());
171 |           }
172 |           if (dataLines.length === 0) continue;
173 |           let data: unknown;
174 |           try {
175 |             data = JSON.parse(dataLines.join("\n"));
176 |           } catch {
177 |             data = dataLines.join("\n");
178 |           }
179 |           events.push({ name, data });
180 |           eventTypes.add(name);
181 |           if (name === "hint") hints.push(data as { level: number; tag?: string; text: string });
182 |           else if (name === "approval") approvals.push(data as { toolName?: string; commands?: string[]; allowed?: boolean; reason?: string });
183 |           else if (name === "tool_call") toolCalls.push(data as { toolName?: string });
184 |           else if (name === "status" && data && typeof (data as { status?: unknown }).status === "string") {
185 |             lastStatus = (data as { status: string }).status;
186 |           }
187 |         }
188 |       }
189 |     } catch {
190 |       // stream aborted/closed — expected at the end
191 |     }
192 |   })();
193 | 
194 | 
195 | 
196 | 
197 |   try {
198 |     // The agent was started in the background by POST; wait for the level-1 hint.
199 |     await waitUntil(() => hints.some((h) => h.level === 1), "level-1 hint over SSE", 240000);
200 | 
201 |     // The hint is delivered *during* the turn; wait for the agent to finish that
202 |     // turn (busy=false) before asking for the next level.
203 |     await waitUntil(() => lastStatus === "idle" || lastStatus === "complete", "agent idle after level-1 hint", 120000);
204 | 
205 |     // Ask for level 2.
206 |     let nh = await fetch(`${BASE}/api/session/${sessionId}/next-hint`, { method: "POST" });
207 |     check(nh.status === 200, `next-hint (level 2) -> 200 (got ${nh.status})`);
208 |     console.log("next-hint (level 2) response:", await nh.clone().json());
209 |     await waitUntil(() => hints.some((h) => h.level === 2), "level-2 hint over SSE", 240000);
210 | 
211 |     // Ask for level 3.
212 |     nh = await fetch(`${BASE}/api/session/${sessionId}/next-hint`, { method: "POST" });
213 |     check(nh.status === 200, `next-hint (level 3) -> 200 (got ${nh.status})`);
214 |     console.log("next-hint (level 3) response:", await nh.clone().json());
215 |     await waitUntil(() => hints.some((h) => h.level === 3), "level-3 hint over SSE", 240000);
216 | 
217 |     // A fourth request should report "complete".
218 |     nh = await fetch(`${BASE}/api/session/${sessionId}/next-hint`, { method: "POST" });
219 |     const nh4 = (await nh.json()) as { status?: string; level?: number; message?: string };
220 |     check(nh4.status === "complete", `next-hint after level 3 -> complete (got ${JSON.stringify(nh4)})`);
221 |     console.log("next-hint (after level 3) response:", nh4);
222 |   } finally {
223 |     controller.abort();
224 |     await streamTask;
225 |   }
226 | 
227 |   // --- assertions ---
228 |   console.log("\n=== assertions ===");
229 |   const byLevel = (l: number) => hints.filter((h) => h.level === l);
230 |   check(byLevel(1).length === 1, `exactly one accepted level-1 hint (got ${byLevel(1).length})`);
231 |   check(byLevel(2).length === 1, `exactly one accepted level-2 hint (got ${byLevel(2).length})`);
232 |   check(byLevel(3).length === 1, `exactly one accepted level-3 hint (got ${byLevel(3).length})`);
233 |   check(hints.length === 3, `exactly 3 accepted hints total (got ${hints.length})`);
234 | 
235 |   for (const h of hints) {
236 |     const g = checkHint(h.text);
237 |     check(g.ok, `hint level ${h.level} passes the guard on re-check (${g.ok ? "ok" : g.reason})`);
238 |     check(!hasCodeMarker(h.text), `hint level ${h.level} has no code marker`);
239 |   }
240 | 
241 |   const WRITE_TOOLS = new Set(["editor", "apply_patch", "fetch_web_content", "skills", "submit_and_exit"]);
242 |   const writeCalls = toolCalls.filter((t) => t.toolName && WRITE_TOOLS.has(t.toolName));
243 |   check(
244 |     writeCalls.length === 0,
245 |     `no edit/write/network tool was executed (found ${writeCalls.map((t) => t.toolName).join(",") || "none"})`,
246 |   );
247 | 
248 |   for (const a of approvals) {
249 |     const cmds = Array.isArray(a.commands) ? a.commands : [];
250 |     const localDecision = allowCommands(cmds);
251 |     check(
252 |       localDecision.allowed === a.allowed,
253 |       `approval decision consistent for ${JSON.stringify(cmds)} (server said ${a.allowed})`,
254 |     );
255 |   }
256 | 
257 |   // --- report ---
258 |   console.log("\n=== hints (verbatim) ===");
259 |   for (const h of hints) {
260 |     console.log(`\n[level ${h.level}${h.tag ? ` (${h.tag})` : ""}]`);
261 |     console.log(h.text);
262 |   }
263 | 
264 |   console.log("\n=== distinct SSE event types ===");
265 |   console.log([...eventTypes].sort().join(", "));
266 | 
267 |   console.log("\n=== approval decisions ===");
268 |   if (approvals.length === 0) {
269 |     console.log("(none — the agent requested no command approvals during this run)");
270 |   }
271 |   for (const a of approvals) {
272 |     console.log(`${a.allowed ? "APPROVED" : "DENIED"}  ${JSON.stringify(a.commands)}${a.reason ? `  (${a.reason})` : ""}`);
273 |   }
274 | }
