```ts
export interface RunInWorkdirResult {
  build: BuildResult | null;
  tests: TestResult[];
  passed: number;
  failed: number;
  total: number;
}

export async function runTestsInWorkdir(
  assignment: Assignment,
  workdir: string,
  testName?: string,
): Promise<RunInWorkdirResult> {
  const runTimeoutMs = RUN_TIMEOUT_MS;
  const buildTimeoutMs = BUILD_TIMEOUT_MS;
  const maxOutputBytes = MAX_OUTPUT_BYTES;

  let build: BuildResult | null = null;
  if (assignment.build) {
    const b = await spawnCommand(assignment.build, { cwd: workdir, timeoutMs: buildTimeoutMs, maxOutputBytes });
    build = { ok: !b.timedOut && b.exitCode === 0, stdout: b.stdout, stderr: b.stderr, timedOut: b.timedOut, signal: b.signal };
    if (!build.ok) {
      return { build, tests: [], passed: 0, failed: 0, total: 0 };
    }
  }

  const testsToRun = testName
    ? assignment.tests.filter((t) => slugifyTestName(t.name) === testName)
    : assignment.tests;

  const tests: TestResult[] = [];
  for (const test of testsToRun) {
    const r = await spawnCommand(assignment.run, { cwd: workdir, input: test.input, timeoutMs: runTimeoutMs, maxOutputBytes });
    const got = r.stdout.trim();
    const passed = !r.timedOut && r.exitCode === 0 && got === test.expected;
    tests.push({ name: test.name, input: test.input, expected: test.expected, got, stderr: r.stderr, exitCode: r.exitCode, signal: r.signal, timedOut: r.timedOut, passed });
  }

  const passed = tests.filter((t) => t.passed).length;
  return { build, tests, passed, failed: tests.length - passed, total: tests.length };
}
```

