  background: linear-gradient(180deg, #16233b, var(--bg));
}

.site-header h1 {
  margin: 0;
  font-size: 2.4rem;
  letter-spacing: -0.02em;
}

.tagline {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 1.1rem;
}

.layout {
  display: grid;
  grid-template-columns: minmax(360px, 1fr) minmax(400px, 1.2fr);
